hsd:
Geometry = GenFormat {
  <<< "geo.gen"
}
Hamiltonian = DFTB {
  SCC = Yes
  SCCTolerance = 1e-10
  MaxSCCIterations = 500
  ShellResolvedSCC = No
  Charge = 0.0
  SlaterKosterFiles = Type2FileNames {
    Prefix = "/tmp/pydftb_ref_vqtom50v/plain/"
    Separator = "-"
    Suffix = ".skf"
  }
  MaxAngularMomentum {
    Cu = "d"
    C = "p"
    O = "p"
  }
  Filling = Fermi {
    Temperature [K] = 300.0
  }

}
Analysis {
  ProjectStates {
    Region {
      Atoms = 1 2 3 4
      ShellResolved = Yes
      Label = "cu"
    }
    Region {
      Atoms = 5
      OrbitalResolved = Yes
      Label = "c"
    }
    Region {
      Atoms = 6
      Label = "o"
    }
  }
  PrintForces = Yes
  MullikenAnalysis = Yes
}
Options {
  WriteDetailedOut = Yes
  WriteResultsTag = Yes
  TimingVerbosity = 0
}
ParserOptions {
  ParserVersion = 14
}
Parallel {
  UseOmpThreads = Yes
}
